package com.pranit.productsupport.core.api;
import com.pranit.productsupport.core.service.ApiException; import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.Map; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.validation.FieldError; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.MissingRequestHeaderException; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice;
@RestControllerAdvice public class GlobalExceptionHandler {
 private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);
 @ExceptionHandler(ApiException.class) ResponseEntity<?> api(ApiException e,HttpServletRequest r){return build(e.getStatus(),e.getMessage(),r);}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e,HttpServletRequest r){String msg=e.getBindingResult().getFieldErrors().stream().map(f->f.getField()+": "+f.getDefaultMessage()).findFirst().orElse("Request validation failed");return build(HttpStatus.BAD_REQUEST,msg,r);}
 @ExceptionHandler(HttpMessageNotReadableException.class) ResponseEntity<?> malformed(HttpMessageNotReadableException e,HttpServletRequest r){return build(HttpStatus.BAD_REQUEST,"Malformed request body or unsupported enum value",r);}
 @ExceptionHandler(MissingRequestHeaderException.class) ResponseEntity<?> missingHeader(MissingRequestHeaderException e,HttpServletRequest r){return build(HttpStatus.BAD_REQUEST,"Missing required header: "+e.getHeaderName(),r);}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> conflict(DataIntegrityViolationException e,HttpServletRequest r){return build(HttpStatus.CONFLICT,"The request conflicts with existing data",r);}
 @ExceptionHandler(Exception.class) ResponseEntity<?> unexpected(Exception e,HttpServletRequest r){log.error("Unhandled request error: {} {}",r.getMethod(),r.getRequestURI(),e);return build(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",r);}
 private ResponseEntity<?> build(HttpStatus status,String message,HttpServletRequest r){return ResponseEntity.status(status).body(Map.of("timestamp",Instant.now().toString(),"status",status.value(),"error",status.getReasonPhrase(),"message",message,"path",r.getRequestURI()));}
}
